	// ConsistentHash configures the hash policies used by consistent hashing load balancers
	// (e.g. RingHash, Maglev) to compute the hash key for requests on a route.
	// If set to an empty object, the request's source IP address is used as the hash key.
	// When multiple policies are merged, the array fields are unioned with entries from
	// the higher-priority policy taking precedence.
	// NOTE: This field is only honored for route-level attachment (HTTPRoute and GRPCRoute targets).
	// +optional
	ConsistentHash *ConsistentHash `json:"consistentHash,omitempty"`
}

// ConsistentHash configures the hash policies used to compute the hash key for consistent
// hashing load balancers. Hash policies are evaluated in the following order: headers,
// cookies, queryParameters, filterState, sourceIp.
// +kubebuilder:validation:XValidation:rule="!has(self.disable) || !self.disable || (!has(self.headers) && !has(self.cookies) && !has(self.queryParameters) && !has(self.filterState) && !has(self.sourceIp))",message="no other fields may be set when disable is true"
type ConsistentHash struct {
	// Disable suppresses consistent hashing on the route, including any hash policies
	// inherited from broader-scoped policies. When true, no other fields may be set.
	// +optional
	Disable *bool `json:"disable,omitempty"`

	// Headers specifies request headers to use as components of the hash key.
	// Entries are deduplicated by headerName (case-insensitive); only the first occurrence is kept.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	Headers []ConsistentHashHeader `json:"headers,omitempty"`

	// Cookies specifies cookies to use as components of the hash key.
	// Entries are deduplicated by name; only the first occurrence is kept.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	Cookies []ConsistentHashCookie `json:"cookies,omitempty"`

	// QueryParameters specifies URL query parameters to use as components of the hash key.
	// Entries are deduplicated by name; only the first occurrence is kept.
	// +optional
	// +kubebuilder:validation:MinItems=1
	// +kubebuilder:validation:MaxItems=16
	QueryParameters []ConsistentHashQueryParameter `json:"queryParameters,omitempty"`

	// FilterState specifies filter state objects to use as components of the hash key.
	// Entries are deduplicated by key; only the first occurrence is kept.
	// +optional
	// +kubebuilder:validation:MinItems=1
